// Applies the server's SQL migrations (packages/server/drizzle, generated by drizzle-kit) to DATABASE_URL.
// `pnpm db:migrate` runs this file; integration tests call runMigrations() before starting a server.
import { realpathSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { drizzle } from 'drizzle-orm/postgres-js';
import { migrate } from 'drizzle-orm/postgres-js/migrator';
import postgres from 'postgres';
import { loadDotEnv, parseConfig } from '../config.ts';

export const MIGRATIONS_FOLDER = fileURLToPath(new URL('../../drizzle', import.meta.url));

/** Serialises concurrent migrators (several test runs or servers against one database). */
const MIGRATION_LOCK = 0x61737472; // "astr"

export async function runMigrations(databaseUrl: string): Promise<void> {
  const sql = postgres(databaseUrl, { max: 1, onnotice: () => {} });
  try {
    await sql`select pg_advisory_lock(${MIGRATION_LOCK})`;
    try {
      await migrate(drizzle({ client: sql }), { migrationsFolder: MIGRATIONS_FOLDER });
    } finally {
      await sql`select pg_advisory_unlock(${MIGRATION_LOCK})`;
    }
  } finally {
    await sql.end({ timeout: 5 });
  }
}

function isEntryPoint(): boolean {
  const argv1 = process.argv[1];
  if (!argv1) return false;
  try {
    return realpathSync(argv1) === realpathSync(fileURLToPath(import.meta.url));
  } catch {
    return false;
  }
}

if (isEntryPoint()) {
  loadDotEnv();
  const config = parseConfig(process.env);
  const target = config.DATABASE_URL.replace(/\/\/[^@/]*@/, '//***@');
  try {
    await runMigrations(config.DATABASE_URL);
    console.log(`db:migrate: ${target} is up to date`);
  } catch (err) {
    console.error(`db:migrate: failed against ${target} (is \`pnpm db:up\` running?)`);
    console.error(err);
    process.exit(1);
  }
}
